'use strict';
(()=>{
 const S=LensMonitorStore,O=LensOperations,q=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={queued:'排队',validating:'校验中',computing:'重算中',awaiting_confirmation:'等待确认',publishing:'发布中',succeeded:'成功',duplicate:'重复批次',failed:'失败',canceled:'已取消',interrupted:'已中断',publication_pending:'监控同步待重试',pending:'待处理',in_progress:'处理中',closed:'已关闭',business:'经营异常',fulfillment:'履约异常',data_quality:'数据质量异常',shop:'全店',product:'商品',category:'品类',seller:'卖家'};
 const label=x=>labels[x]||x,fmt=n=>n==null?'不适用':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n),short=s=>String(s||'—').slice(0,12);
 let currentResult=null,selected=null,view=0,page=0,stateCache=null,selectedRun=null;
 const locks=new Map();
 async function hold(id){if(!navigator.locks)throw Error('浏览器不支持任务互斥锁，请更新浏览器');await new Promise((resolve,reject)=>{navigator.locks.request('olist-job:'+id,async()=>{await new Promise(release=>{locks.set(id,release);resolve();});}).catch(reject);});}
 function release(id){locks.get(id)?.();locks.delete(id);}
 async function refresh(){if(currentResult)await render(currentResult);}
 async function start(files,manifest){const id=crypto.randomUUID(),at=new Date().toISOString(),raw=await O.hash({files,manifest}),file_hashes=Object.fromEntries(await Promise.all(Object.entries(files).map(async([k,v])=>[k,await O.hash(v)])));await hold(id);try{await S.mutate(s=>{const previous=Object.values(s.jobs).filter(j=>j.raw_batch_hash===raw).sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at))[0];S.createJob(s,{job_id:id,attempt_id:id,retry_of:previous&&['failed','interrupted','canceled'].includes(previous.status)?previous.job_id:null,file_hashes,submitted_at:at,started_at:at,trigger:'manual',mode:manifest.monitoring?.mode||'historical_replay',raw_batch_hash:raw,source:manifest.source_uri_or_description,source_extracted_at:manifest.extracted_at,coverage_start:manifest.coverage_start,coverage_end:manifest.coverage_end});S.transition(s,id,'validating');});return id;}catch(e){release(id);throw e;}}
 async function phase(id){await S.mutate(s=>{if(s.jobs[id]?.status==='validating')S.transition(s,id,'computing');});}
 async function failure(id,detail,kind='data_quality'){
  if(!id)return;const state=await S.read(),job=state.jobs[id];if(!job)return;
  const code=Array.isArray(detail)?detail.map(x=>x.code||x).join('|'):String(detail),event_id=await O.hash({raw:job.raw_batch_hash,rule:'quality-2.0.0',code});
  await S.mutate(s=>{if(!['failed','canceled','interrupted','succeeded','duplicate'].includes(s.jobs[id].status))S.transition(s,id,'failed',{error_code:kind,error_summary:code});if(kind==='data_quality')S.qualityEvent(s,id,{event_id,event_type:'data_quality',rule_id:'batch_quality',rule_version:'quality-2.0.0',metric_id:'quality_gate',metric_label:'批次质量门禁',scope_type:'shop',entity_id:'attempted_batch',status:'pending',severity:'high',dataset_version:null,accepted_dataset_version:null,attempted_batch_hash:job.raw_batch_hash,source_ref:{source:job.source,source_extracted_at:job.source_extracted_at,file_hashes:job.file_hashes},calculation_version:'monitoring-2.0.1',evidence:{rule:code,checks:detail},evidence_ids:[event_id+':quality'],created_at:new Date().toISOString(),updated_at:new Date().toISOString()});});release(id);await refresh();
 }
 async function ready(id,result){await phase(id);if(result.monitoring?.status!=='verified'){await failure(id,result.monitoring?.gates||['missing_monitoring_configuration']);return;}await S.mutate(s=>S.transition(s,id,'awaiting_confirmation',{dataset_version:result.monitoring.dataset_version,run_id:result.monitoring.run_id,v1_snapshot_id:result.id}));}
 async function cancel(id){if(!id)return;await S.mutate(s=>{if(['queued','validating','computing','awaiting_confirmation'].includes(s.jobs[id]?.status))S.transition(s,id,'canceled');});release(id);}
 async function prepare(staged){if(staged.result.monitoring?.status==='verified')await S.mutate(s=>S.transition(s,staged.monitor_job_id,'publishing'));}
 async function publish(staged){if(staged.result.monitoring?.status!=='verified')return;try{await S.mutate(s=>S.publish(s,staged.monitor_job_id,staged.result.monitoring));release(staged.monitor_job_id);}catch(e){try{await S.mutate(s=>S.transition(s,staged.monitor_job_id,'publication_pending',{error_summary:e.message}));}catch(_){}release(staged.monitor_job_id);throw e;}}
 async function recover(snapshots){
  const jobs=Object.values((await S.read()).jobs);
  for(const job of jobs){if(!['queued','validating','computing','awaiting_confirmation','publishing','publication_pending'].includes(job.status))continue;
   await navigator.locks.request('olist-job:'+job.job_id,{ifAvailable:true},async lock=>{
    if(!lock)return;
    const latest=typeof getSnapshots==='function'?await getSnapshots():snapshots;
    await S.mutate(s=>{const j=s.jobs[job.job_id];if(['publishing','publication_pending'].includes(j.status)){const saved=latest.find(x=>x.id===j.v1_snapshot_id&&x.result.monitoring?.run_id===j.run_id);if(saved)S.publish(s,j.job_id,saved.result.monitoring);else S.transition(s,j.job_id,j.status==='publication_pending'?'canceled':'failed',{error_summary:'未找到已提交的完整快照，未发布监控结果'});}else if(['queued','validating','computing','awaiting_confirmation'].includes(j.status))S.transition(s,j.job_id,'interrupted',{error_summary:'页面关闭或刷新中断；请重新提交原文件，系统会去重'});});
   });
  }
  await refresh();
 }
 function detail(id){selected=id;const e=stateCache.events[id];if(!e)return;q('#mon-detail-title').textContent=label(e.event_type)+' · '+(e.metric_label||e.rule_id)+' · '+(e.entity_id??'未知');q('#mon-evidence').textContent=JSON.stringify({...e,processing_history:stateCache.event_history.filter(h=>h.event_id===id)},null,2);q('#mon-detail').classList.remove('hidden');q('#mon-event-status').textContent=label(e.status);q('#mon-status').innerHTML=({pending:['in_progress','closed'],in_progress:['closed','pending'],closed:['pending']}[e.status]||[]).map(s=>`<option value="${s}">${label(s)}</option>`).join('');q('#mon-evidence-ref').value=e.evidence_ids?.join(', ')||'';}
 async function render(result){currentResult=result;const token=++view;try{const s=await S.read();if(token!==view)return;stateCache=s;const actualRun=s.snapshot_runs[result.id],versions=q('#mon-version'),previous=versions.value;versions.innerHTML='<option value="current">当前分析版本</option>'+Object.values(s.runs).sort((a,b)=>b.published_at.localeCompare(a.published_at)).map(r=>`<option value="${r.run_id}">${short(r.dataset_version)} · ${escape(r.source_ref.manifest.dataset_name)} · ${r.comparison.after.start}</option>`).join('');versions.value=previous&&[...versions.options].some(o=>o.value===previous)?previous:'current';const run=s.runs[versions.value==='current'?actualRun:versions.value];selectedRun=run;
  const currentEvents=run?Object.values(s.events).filter(e=>e.analysis_run_id===run.run_id):[],jobs=Object.values(s.jobs).sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at));
  q('#mon-summary').textContent=run?`${run.mode==='historical_replay'?'历史回放':'手动快照'} · ${run.is_synthetic===true?'合成测试样本':run.is_synthetic===false?'非合成数据':'样本性质未声明'} · 来源提取时间 ${run.source_ref.manifest.extracted_at} · 完整至 ${run.completeness.through} · 最近计算 ${run.generated_at}`:'当前版本尚未生成可验证监控结果。导入带完整周期配置的 CSV 快照后自动校验重算；现有公开案例为历史数据。';
  q('#mon-cards').innerHTML=[['数据版本',run?short(run.dataset_version):'未建立'],['当前经营 / 履约待处理',currentEvents.filter(e=>e.status!=='closed').length],['规则被抑制',run?.evaluations.filter(e=>e.suppressed_reasons.length).length??'—'],['后台调度','未接入 / 未启用']].map(([a,b])=>`<div class="quality-tile"><span class="tiny-label">${a}</span><strong>${escape(b)}</strong></div>`).join('');
  const shop=run?.evaluations.filter(e=>e.scope_type==='shop'&&e.metric_id!=='late_rate')||[];q('#mon-metrics').innerHTML=shop.map(e=>{const money=e.metric_id.includes('cents'),unit=money?run.source_ref.manifest.currency:e.unit,scale=money?100:1;return `<div class="quality-tile"><span class="tiny-label">${escape(e.metric_label)}</span><strong>${fmt(e.after==null?null:e.after/scale)} ${escape(unit)}</strong><small>基期 ${fmt(e.before==null?null:e.before/scale)} · 变化 ${fmt(e.absolute_change==null?null:e.absolute_change/scale)}<br>${e.suppressed_reasons.length?'证据不足，告警被抑制':e.fired?'触发异常，待核查':'未触发规则'}</small></div>`;}).join('');
  q('#mon-suppressed').textContent=run?JSON.stringify(run.evaluations.filter(e=>e.suppressed_reasons.length).map(e=>({scope:label(e.scope_type),entity:e.entity_id,metric:e.metric_label,reasons:e.suppressed_reasons})),null,2):'证据不足';
  q('#mon-ranking').innerHTML=run?.negative_products.length?run.negative_products.slice(0,50).map(r=>`<tr><td>${escape(r.key??'未知商品')}</td><td>${fmt(r.before.amount_cents/100)}</td><td>${fmt(r.after.amount_cents/100)}</td><td class="status-error">${fmt(r.delta_cents/100)}</td><td>${escape(r.flags.join(', ')||'—')}</td><td><button class="button ghost small-button" data-mon-product="${escape(r.evidence_id)}">证据</button></td></tr>`).join(''):'<tr><td colspan="6">无已验证的下降商品；不以正向抵消贡献作为下降排名。</td></tr>';
  q('#mon-jobs').innerHTML=jobs.slice(0,100).map(j=>`<tr><td><code>${short(j.job_id)}</code></td><td>${label(j.status)}</td><td>${escape(j.source_extracted_at||'—')}</td><td>${escape(j.finished_at||j.started_at)}</td><td>${short(j.dataset_version)}</td><td>${escape(j.error_summary||'—')}</td></tr>`).join('')||'<tr><td colspan="6">尚无更新任务</td></tr>';
  const all=q('#mon-history').checked;let events=Object.values(s.events).filter(e=>all||e.event_type==='data_quality'||run&&e.analysis_run_id===run.run_id);const type=q('#mon-type').value,status=q('#mon-filter-status').value,scope=q('#mon-scope').value;
  events=events.filter(e=>(!type||e.event_type===type)&&(!status||e.status===status)&&(!scope||e.scope_type===scope)).sort((a,b)=>b.created_at.localeCompare(a.created_at));page=Math.min(page,Math.max(0,Math.ceil(events.length/25)-1));q('#mon-page').textContent=`${events.length} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(events.length/25))} 页`;q('#mon-prev').disabled=page===0;q('#mon-next').disabled=(page+1)*25>=events.length;
  q('#mon-events').innerHTML=events.slice(page*25,page*25+25).map(e=>`<tr><td>${label(e.event_type)}<br><small>${short(e.dataset_version||e.attempted_batch_hash)}</small></td><td>${label(e.scope_type)} / ${escape(e.entity_id??'未知')}</td><td>${escape(e.metric_label)}</td><td>${e.metric_id==='late_rate'?fmt(e.percentage_point_change)+' 个百分点':fmt(e.absolute_change)+' '+escape(e.unit||'')}<br><small>${e.relative_change==null?'无可用百分比':fmt(e.relative_change*100)+'%'}</small></td><td>${label(e.status)}</td><td><button class="button ghost small-button" data-mon-event="${e.event_id}">查看 / 处理</button></td></tr>`).join('')||'<tr><td colspan="6">此筛选下没有告警。被抑制规则不等于指标正常。</td></tr>';
  document.querySelectorAll('[data-mon-event]').forEach(b=>b.onclick=()=>detail(b.dataset.monEvent));document.querySelectorAll('[data-mon-product]').forEach(b=>b.onclick=()=>{const row=run.negative_products.find(r=>r.evidence_id===b.dataset.monProduct);q('#mon-product-evidence').textContent=JSON.stringify({dataset_version:run.dataset_version,source:run.source_ref,...row},null,2);q('#mon-product-details').open=true;});if(selected&&s.events[selected])detail(selected);
 }catch(e){q('#mon-summary').textContent='监控存储读取失败：'+e.message;}}
 document.addEventListener('DOMContentLoaded',()=>{
  for(const id of ['mon-version','mon-type','mon-filter-status','mon-scope','mon-history'])q('#'+id).addEventListener('change',()=>{page=0;refresh();});q('#mon-prev').onclick=()=>{page--;refresh();};q('#mon-next').onclick=()=>{page++;refresh();};q('#mon-refresh').onclick=refresh;
  q('#mon-recover').onclick=async()=>{try{await recover(await getSnapshots());q('#mon-action-message').textContent='已核对完整快照并重试待同步任务。其他失败任务请修正输入后重新导入。';}catch(e){q('#mon-action-message').textContent=e.message;}};
  q('#mon-handle-form').onsubmit=async e=>{e.preventDefault();try{await S.mutate(s=>S.changeStatus(s,selected,{status:q('#mon-status').value,actor:q('#mon-actor').value,note:q('#mon-note').value,resolution_code:q('#mon-resolution').value,evidence_ref:q('#mon-evidence-ref').value}));q('#mon-action-message').textContent='处理记录已保存。指标恢复不证明行动有效。';await refresh();}catch(err){q('#mon-action-message').textContent=err.message;}};
  q('#mon-export').onclick=async()=>{const data=await S.read();download('olist-monitoring-audit.json',JSON.stringify({exported_at:new Date().toISOString(),storage:'local_browser',...data},null,2));};
 });
 window.MonitorController={start,phase,ready,failure,cancel,prepare,publish,recover,release,render};window.renderMonitoring=render;
})();
